# fleet_env_name_retired NAME — true when NAME is a removed spelling, or one
# with a per-account suffix (<BASE>_<ACCOUNT>, ACCOUNT upper-case letters,
# digits and underscores — creds.ApplyClientSuffix's grammar), exactly as
# envreg.RetiredAlias decides.
fleet_env_name_retired() {
  local name="$1" base rest
  [[ "$FLEET_RETIRED_ENV_NAMES" == *" $name "* ]] && return 0
  base="$name"
  while [[ "$base" == *_* ]]; do
    base="${base%_*}"
    rest="${name#"$base"_}"
    if [[ "$rest" =~ ^[A-Z0-9][A-Z0-9_]*$ && "$FLEET_RETIRED_ENV_NAMES" == *" $base "* ]]; then
      return 0
    fi
  done
  return 1
}
